-- Conventions
--   * Primary keys are UUIDv7 strings (time-ordered), generated by the app.
--   * Timestamps are epoch milliseconds (INTEGER).
--   * Money is stored in paise (INTEGER). Never floats.
--   * GST rates are basis points (12% = 1200).
--   * Every table carries created_at / updated_at / version / deleted_at so it can sync later.

CREATE TABLE app_user (
    id             TEXT    PRIMARY KEY,
    created_at     INTEGER NOT NULL,
    updated_at     INTEGER NOT NULL,
    version        INTEGER NOT NULL DEFAULT 0,
    deleted_at     INTEGER,
    name           TEXT    NOT NULL,
    username       TEXT    NOT NULL COLLATE NOCASE UNIQUE,
    password_hash  TEXT    NOT NULL,
    role           TEXT    NOT NULL CHECK (role IN ('ADMIN', 'MANAGER', 'CASHIER')),
    web_access     INTEGER NOT NULL DEFAULT 0,
    active         INTEGER NOT NULL DEFAULT 1,
    last_login_at  INTEGER
);

CREATE TABLE auth_token (
    id            TEXT    PRIMARY KEY,
    created_at    INTEGER NOT NULL,
    updated_at    INTEGER NOT NULL,
    version       INTEGER NOT NULL DEFAULT 0,
    deleted_at    INTEGER,
    token_hash    TEXT    NOT NULL UNIQUE,
    user_id       TEXT    NOT NULL REFERENCES app_user (id),
    channel       TEXT    NOT NULL,
    ip            TEXT,
    user_agent    TEXT,
    expires_at    INTEGER NOT NULL,
    last_seen_at  INTEGER NOT NULL
);
CREATE INDEX idx_auth_token_user ON auth_token (user_id);

CREATE TABLE shop_settings (
    id              TEXT    PRIMARY KEY,
    created_at      INTEGER NOT NULL,
    updated_at      INTEGER NOT NULL,
    version         INTEGER NOT NULL DEFAULT 0,
    deleted_at      INTEGER,
    shop_name       TEXT    NOT NULL,
    gstin           TEXT,
    state_code      TEXT,
    address         TEXT,
    phone           TEXT,
    invoice_prefix  TEXT    NOT NULL DEFAULT 'INV',
    lan_enabled     INTEGER NOT NULL DEFAULT 0,
    public_enabled  INTEGER NOT NULL DEFAULT 0,
    tunnel_token    TEXT,
    public_url      TEXT
);

CREATE TABLE item (
    id           TEXT    PRIMARY KEY,
    created_at   INTEGER NOT NULL,
    updated_at   INTEGER NOT NULL,
    version      INTEGER NOT NULL DEFAULT 0,
    deleted_at   INTEGER,
    name         TEXT    NOT NULL,
    code         TEXT,
    barcode      TEXT,
    hsn          TEXT,
    unit         TEXT    NOT NULL DEFAULT 'NOS',
    rate_paise   INTEGER NOT NULL CHECK (rate_paise >= 0),
    gst_rate_bp  INTEGER NOT NULL CHECK (gst_rate_bp >= 0 AND gst_rate_bp <= 4000),
    stock_qty    INTEGER NOT NULL DEFAULT 0,
    active       INTEGER NOT NULL DEFAULT 1
);
CREATE INDEX idx_item_name ON item (name COLLATE NOCASE);
CREATE INDEX idx_item_barcode ON item (barcode);

-- Sequential, gap-free invoice numbers per financial year (GST requirement).
CREATE TABLE invoice_sequence (
    fy           TEXT    PRIMARY KEY,
    last_number  INTEGER NOT NULL
);

CREATE TABLE invoice (
    id               TEXT    PRIMARY KEY,
    created_at       INTEGER NOT NULL,
    updated_at       INTEGER NOT NULL,
    version          INTEGER NOT NULL DEFAULT 0,
    deleted_at       INTEGER,
    invoice_no       TEXT    NOT NULL UNIQUE,
    fy               TEXT    NOT NULL,
    seq              INTEGER NOT NULL,
    invoice_date     INTEGER NOT NULL,
    customer_name    TEXT,
    customer_phone   TEXT,
    customer_gstin   TEXT,
    inter_state      INTEGER NOT NULL DEFAULT 0,
    payment_mode     TEXT    NOT NULL,
    taxable_paise    INTEGER NOT NULL,
    cgst_paise       INTEGER NOT NULL,
    sgst_paise       INTEGER NOT NULL,
    igst_paise       INTEGER NOT NULL,
    round_off_paise  INTEGER NOT NULL,
    total_paise      INTEGER NOT NULL,
    created_by       TEXT    NOT NULL REFERENCES app_user (id),
    channel          TEXT    NOT NULL,
    UNIQUE (fy, seq)
);
CREATE INDEX idx_invoice_date ON invoice (invoice_date);

CREATE TABLE invoice_line (
    id             TEXT    PRIMARY KEY,
    created_at     INTEGER NOT NULL,
    updated_at     INTEGER NOT NULL,
    version        INTEGER NOT NULL DEFAULT 0,
    deleted_at     INTEGER,
    invoice_id     TEXT    NOT NULL REFERENCES invoice (id),
    line_no        INTEGER NOT NULL,
    item_id        TEXT    REFERENCES item (id),
    name           TEXT    NOT NULL,
    hsn            TEXT,
    qty            INTEGER NOT NULL CHECK (qty > 0),
    rate_paise     INTEGER NOT NULL,
    gst_rate_bp    INTEGER NOT NULL,
    taxable_paise  INTEGER NOT NULL,
    cgst_paise     INTEGER NOT NULL,
    sgst_paise     INTEGER NOT NULL,
    igst_paise     INTEGER NOT NULL,
    total_paise    INTEGER NOT NULL
);
CREATE INDEX idx_invoice_line_invoice ON invoice_line (invoice_id);
